const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Jakarta Bay coastal area (approximate bounding box)
  const jakartaBay = ee.Geometry.Rectangle([106.6, -6.3, 107.0, -5.9]);

  // Use Sentinel-2 data for 2021
  const startDate = '2021-01-01';
  const endDate = '2021-12-31';

  let col = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(jakartaBay)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const imgCount = col.size().getInfo();
  print(`2021 Images: ${imgCount}`);

  if (imgCount === 0) {
    print("No Sentinel-2 images found, trying Landsat 8...");
    col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(jakartaBay)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    const lsCount = col.size().getInfo();
    print(`Landsat 8 Images: ${lsCount}`);
    if (lsCount === 0) {
      print("No data found for Jakarta Bay in 2021.");
      print("C1");
      return;
    }
  }

  // Create median composite
  let img = col.median();

  // For Sentinel-2: Calculate NDBI (Normalized Difference Built-up Index)
  // NDBI = (SWIR - NIR) / (SWIR + NIR)
  // B11 = SWIR, B8 = NIR
  const ndbi = img.normalizedDifference(['B11', 'B8']).rename('ndbi');

  // Classify as built-up where NDBI > 0.1 (threshold for artificial surfaces)
  const builtUp = ndbi.gt(0.1).rename('buildup');

  // Calculate pixel count
  const pixelCount = builtUp.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: jakartaBay,
    scale: 10,
    maxPixels: 1e9
  }).get('buildup').getInfo();

  print(`Valid pixels: ${pixelCount}`);

  if (pixelCount === null || pixelCount === 0) {
    print("No valid pixels after processing.");
    print("C2");
    return;
  }

  // Calculate area of built-up pixels
  // Sentinel-2 resolution: 10m per pixel = 100 m² per pixel
  // 1 hectare = 10,000 m²
  const pixelAreaM2 = 100;
  const pixelAreaHa = pixelAreaM2 / 10000;
  const totalBuiltUpAreaHa = pixelCount * pixelAreaHa;

  print(`Built-up area: ${totalBuiltUpAreaHa.toFixed(2)} hectares`);
  print(`Threshold: 800 hectares`);

  if (isNaN(totalBuiltUpAreaHa) || totalBuiltUpAreaHa < 0) {
    print("Invalid calculation result.");
    print("C3");
    return;
  }

  if (totalBuiltUpAreaHa > 800) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
